package com.crimson.launcher;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.graphics.drawable.*;import android.provider.Settings;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;import java.text.*;
public class MainActivity extends Activity {
 final int INK=0xfff4eee8,SECOND=0xffbdb0aa,ACCENT=0xffffb4a9;
 FrameLayout root,home;LinearLayout body,homeBody;GridLayout grid,homeGrid;TextView clock;EditText search;boolean library;String category="All";
 ArrayList<ResolveInfo> apps=new ArrayList<>();HashMap<String,String> names=new HashMap<>();HashMap<String,Drawable.ConstantState> icons=new HashMap<>();
 Handler handler=new Handler(Looper.getMainLooper());SimpleDateFormat format=new SimpleDateFormat("HH:mm",Locale.getDefault());float x,y;boolean consumed;
 Runnable tick=new Runnable(){public void run(){updateTime();handler.postDelayed(this,60000-System.currentTimeMillis()%60000);}};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff10131c);getWindow().setNavigationBarColor(0xff10131c);load();showHome();}
 protected void onResume(){super.onResume();updateTime();handler.removeCallbacks(tick);handler.post(tick);}
 protected void onPause(){handler.removeCallbacks(tick);super.onPause();}
 void updateTime(){if(clock!=null)clock.setText(format.format(new Date()));}
 void load(){apps.clear();apps.addAll(getPackageManager().queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0));apps.removeIf(a->a.activityInfo.packageName.equals(getPackageName()));for(ResolveInfo a:apps)names.put(key(a),a.loadLabel(getPackageManager()).toString());apps.sort((a,b)->name(a).compareToIgnoreCase(name(b)));}
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}String key(ResolveInfo a){return a.activityInfo.packageName+"/"+a.activityInfo.name;}String name(ResolveInfo a){return names.get(key(a));}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
 GradientDrawable card(boolean active){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff2a2930,0xff1d2029});d.setCornerRadius(dp(24));d.setStroke(dp(1),active?ACCENT:0x18f4eee8);return d;}
 void gap(int n){body.addView(new View(this),new LinearLayout.LayoutParams(1,dp(n)));}
 void base(){root=new FrameLayout(this);root.addView(new Wallpaper(this),new FrameLayout.LayoutParams(-1,-1));body=column();body.setPadding(dp(24),dp(20),dp(24),dp(12));if(library){ScrollView sc=new ScrollView(this);sc.setVerticalScrollBarEnabled(false);sc.setOverScrollMode(View.OVER_SCROLL_NEVER);sc.setFillViewport(true);sc.addView(body);root.addView(sc);}else root.addView(body,new FrameLayout.LayoutParams(-1,-1));setContentView(root);}
 void showHome(){library=false;if(home!=null){root=home;body=homeBody;grid=homeGrid;setContentView(root);updateTime();return;}base();TextView brand=text("CRIMSON",11,SECOND);brand.setLetterSpacing(.24f);body.addView(brand);gap(24);
 LinearLayout widget=column();widget.setPadding(dp(22),dp(16),dp(22),dp(20));widget.setBackground(card(false));clock=text(format.format(new Date()),62,ACCENT);clock.setTypeface(Typeface.create("sans-serif-light",0));widget.addView(clock);widget.addView(text(new SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date()),15,SECOND));body.addView(widget);gap(20);
 TextView find=text("Search apps",16,SECOND);find.setBackground(card(false));find.setPadding(dp(20),dp(16),dp(20),dp(16));find.setOnClickListener(v->{showLibrary();search.requestFocus();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(search,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});body.addView(find);gap(24);
 grid=new GridLayout(this);grid.setColumnCount(4);body.addView(grid);ArrayList<ResolveInfo> sorted=new ArrayList<>(apps);sorted.sort((a,b)->Boolean.compare(pinned(b),pinned(a)));float height=getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().density;int rows=Math.max(1,Math.min(3,(int)(height-390)/100));for(int i=0;i<Math.min(rows*4,sorted.size());i++)addApp(sorted.get(i));body.addView(new View(this),new LinearLayout.LayoutParams(1,0,1));TextView handle=text("\u2303",24,ACCENT);handle.setGravity(17);handle.setPadding(0,dp(8),0,dp(8));handle.setContentDescription("Swipe up for app library");body.addView(handle);home=root;homeBody=body;homeGrid=grid;}
 boolean pinned(ResolveInfo a){return getPreferences(0).getBoolean(key(a),false);}
 void animateIn(boolean up){body.setTranslationY(dp(up?24:-10));body.setAlpha(.6f);body.animate().translationY(0).alpha(1).setDuration(160).start();}
 void showLibrary(){if(library)return;library=true;base();body.addView(text("App library",28,INK));gap(20);search=new EditText(this);search.setSingleLine();search.setTextSize(16);search.setTextColor(INK);search.setHintTextColor(SECOND);search.setHint("Search installed apps");search.setBackground(card(false));search.setPadding(dp(18),dp(12),dp(18),dp(12));body.addView(search);gap(16);
 HorizontalScrollView sc=new HorizontalScrollView(this);sc.setHorizontalScrollBarEnabled(false);LinearLayout chips=new LinearLayout(this);for(String c:new String[]{"All","Social","Games","Work","Other"}){TextView chip=text(c,14,INK);chip.setPadding(dp(16),dp(10),dp(16),dp(10));chip.setBackground(card(category.equals(c)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(0,0,dp(8),0);chips.addView(chip,p);chip.setOnClickListener(v->{category=c;for(int i=0;i<chips.getChildCount();i++)chips.getChildAt(i).setBackground(card(chips.getChildAt(i)==chip));filter();});}sc.addView(chips);body.addView(sc);gap(24);grid=new GridLayout(this);grid.setColumnCount(4);body.addView(grid);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){filter();}});filter();animateIn(true);}
 String group(ResolveInfo a){switch(a.activityInfo.applicationInfo.category){case ApplicationInfo.CATEGORY_GAME:return "Games";case ApplicationInfo.CATEGORY_SOCIAL:return "Social";case ApplicationInfo.CATEGORY_PRODUCTIVITY:return "Work";default:return "Other";}}
 void filter(){grid.removeAllViews();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);for(ResolveInfo a:apps)if(name(a).toLowerCase(Locale.ROOT).contains(q)&&(category.equals("All")||category.equals(group(a))))addApp(a);if(grid.getChildCount()==0)grid.addView(text("No apps found",16,SECOND));}
 void addApp(ResolveInfo a){LinearLayout cell=column();cell.setGravity(17);cell.setPadding(dp(3),dp(4),dp(3),dp(14));ImageView icon=new ImageView(this);Drawable.ConstantState state=icons.get(key(a));Drawable image;if(state==null){image=a.loadIcon(getPackageManager());if(image.getConstantState()!=null)icons.put(key(a),image.getConstantState());}else image=state.newDrawable(getResources());icon.setImageDrawable(image);icon.setPadding(dp(11),dp(11),dp(11),dp(11));icon.setBackground(card(pinned(a)));cell.addView(icon,new LinearLayout.LayoutParams(dp(60),dp(60)));TextView title=text(name(a),11,SECOND);title.setSingleLine();title.setEllipsize(TextUtils.TruncateAt.END);title.setGravity(17);title.setPadding(0,dp(7),0,0);cell.addView(title,new LinearLayout.LayoutParams(-1,-2));GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.setGravity(Gravity.FILL_HORIZONTAL);grid.addView(cell,p);
 cell.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setComponent(new ComponentName(a.activityInfo.packageName,a.activityInfo.name)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED));}catch(Exception e){Toast.makeText(this,"App unavailable",0).show();}});cell.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle(name(a)).setItems(new String[]{pinned(a)?"Unpin from home":"Pin to home","App info"},(d,n)->{if(n==0){getPreferences(0).edit().putBoolean(key(a),!pinned(a)).apply();home=null;if(library)filter();else showHome();}else startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+a.activityInfo.packageName)));}).show();return true;});}
 void hideKeyboard(){((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);}
 public void onBackPressed(){if(library){hideKeyboard();showHome();animateIn(false);}}
 protected void onNewIntent(Intent i){super.onNewIntent(i);hideKeyboard();showHome();}
 public boolean dispatchTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();consumed=false;}float dx=e.getX()-x,dy=e.getY()-y;
 if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&!library&&!consumed&&((dy<-dp(64)&&Math.abs(dy)>Math.abs(dx)*1.5f)||(x<dp(28)&&dx>dp(64)&&Math.abs(dx)>Math.abs(dy)*1.5f))){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();consumed=true;if(dy<-dp(64))showLibrary();else panel();return true;}
 if(consumed)return true;if(e.getActionMasked()==MotionEvent.ACTION_UP&&!library&&x<dp(22)&&Math.abs(dx)<dp(12)&&Math.abs(dy)<dp(12)){panel();return true;}return super.dispatchTouchEvent(e);}
 void panel(){Dialog dialog=new Dialog(this);LinearLayout col=column();col.setPadding(dp(24),dp(24),dp(24),dp(20));col.setBackground(card(false));col.addView(text("Your space",26,INK));TextView heading=text("CATEGORIES",11,SECOND);heading.setPadding(0,dp(24),0,dp(12));col.addView(heading);for(String c:new String[]{"All","Social","Games","Work","Other"}){TextView item=text(c.equals("All")?"All apps":c,19,INK);item.setPadding(0,dp(16),0,dp(16));col.addView(item);item.setOnClickListener(v->{category=c;dialog.dismiss();showLibrary();});}TextView settings=text("Launcher settings",16,ACCENT);settings.setPadding(0,dp(24),0,dp(16));col.addView(settings);settings.setOnClickListener(v->{dialog.dismiss();settings();});dialog.setContentView(col);Window w=dialog.getWindow();w.setBackgroundDrawableResource(android.R.color.transparent);dialog.show();w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.82f),-2);w.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);}
 void settings(){new AlertDialog.Builder(this).setTitle("Crimson Launcher").setItems(new String[]{"Set default launcher","Refresh installed apps","About"},(d,n)->{if(n==0)startActivity(new Intent(Settings.ACTION_HOME_SETTINGS));else if(n==1){load();icons.clear();home=null;library=false;showHome();}else new AlertDialog.Builder(this).setTitle("Crimson 0.2").setMessage("Soft peach and charcoal. Swipe up for apps. Tap or swipe from the left edge for categories and settings. Long press an app to pin it.").setPositiveButton("Done",null).show();}).show();}
 class Wallpaper extends View{Paint p=new Paint(3);Shader glow;Wallpaper(Context c){super(c);}protected void onSizeChanged(int w,int h,int a,int b){glow=new RadialGradient(w*.12f,h*.08f,w*1.2f,new int[]{0xff383039,0xff1c1e28,0xff10131c},null,Shader.TileMode.CLAMP);}protected void onDraw(Canvas c){p.setShader(glow);c.drawRect(0,0,getWidth(),getHeight(),p);}}
}
